import React, { memo, useEffect, useMemo, useState } from "react";

import api from "../services/api";
import { useAppContext } from "../context/AppContext";

const formatResourceLabel = (resource) =>
  resource.floor
    ? `${resource.name} - ${resource.floor}`
    : resource.name;

const STUDENT_DURATION_OPTIONS = [
  { value: "15", label: "15 Minutes" },
  { value: "30", label: "30 Minutes" },
  { value: "45", label: "45 Minutes" },
  { value: "60", label: "1 Hour" },
];

const BookingForm = ({
  formData = {},
  onChange = () => {},
  onSubmit = () => {},
  onAvailabilityCheck = () => {},
  availabilityMsg,
  successBooking,
  loading,
  currentUser = {},
}) => {
  const { blocks, fetchInitialData } = useAppContext();

  const [resourceRows, setResourceRows] = useState([]);
  const [resourceLoading, setResourceLoading] = useState(false);
  const [resourceError, setResourceError] = useState("");

  const today = new Date().toISOString().slice(0, 10);

  const isStudent =
    currentUser.role === "student" ||
    currentUser.role === "client";

  const safeFormData = {
    resourceScope: "block",
    blockId: "",
    resourceId: "",
    name: "",
    department: "",
    bookingDate: "",
    startTime: "",
    endTime: "",
    duration: "15",
    purpose: "",
    ...formData,
  };

  const blockOptions = useMemo(
    () => blocks || [],
    [blocks]
  );

  useEffect(() => {
    fetchInitialData?.();
  }, [fetchInitialData]);

  const loadResources = async () => {
    setResourceError("");
    setResourceRows([]);

    if (
      safeFormData.resourceScope === "block" &&
      !safeFormData.blockId
    ) {
      return;
    }

    setResourceLoading(true);

    try {
      const url =
        safeFormData.resourceScope === "extra"
          ? "/extra-centers"
          : `/blocks/${safeFormData.blockId}/resources`;

      const response = await api.get(url, {
        cache: false,
      });

      setResourceRows(response.data || []);
    } catch (error) {
      setResourceError(
        "Could not load resources for this selection."
      );
    } finally {
      setResourceLoading(false);
    }
  };

  useEffect(() => {
    loadResources();
  }, [
    safeFormData.blockId,
    safeFormData.resourceScope,
  ]);

  const setField = (name, value) =>
    onChange({
      target: { name, value },
    });

  const handleScopeChange = (value) => {
    if (isStudent && value === "extra") {
      return;
    }

    setField("resourceScope", value);
    setField("blockId", "");
    setField("resourceId", "");
  };

  const handleBlockChange = (event) => {
    setField("blockId", event.target.value);
    setField("resourceId", "");
  };

  return (
    <section className="glass-panel section-panel booking-surface">
      <div className="panel-heading">
        <span className="panel-icon">B</span>

        <div>
          <h2>New Booking</h2>

          <p>
            Choose a block, load its resources,
            check availability, then submit for approval.
          </p>
        </div>
      </div>

      <div className="segmented">
        <button
          type="button"
          className={
            safeFormData.resourceScope === "block"
              ? "active"
              : ""
          }
          onClick={() =>
            handleScopeChange("block")
          }
        >
          Block
        </button>

        {!isStudent ? (
          <button
            type="button"
            className={
              safeFormData.resourceScope === "extra"
                ? "active"
                : ""
            }
            onClick={() =>
              handleScopeChange("extra")
            }
          >
            Extra Centers
          </button>
        ) : null}
      </div>

      <form
        className="modern-form grid-form"
        onSubmit={onSubmit}
      >
        {/* NAME */}

        <label>
          <span>Your Name</span>

          <input
            name="name"
            value={safeFormData.name}
            onChange={onChange}
            required
            readOnly
          />
        </label>

        {/* DEPARTMENT */}

        <label>
          <span>Department</span>

          <select
            name="department"
            value={safeFormData.department}
            onChange={onChange}
            required
          >
            <option value="">
              Select Department
            </option>

            {Array.from(
              { length: 9 },
              (_, index) => {
                const letter =
                  String.fromCharCode(65 + index);

                return (
                  <option
                    key={letter}
                    value={`Department ${letter}`}
                  >
                    Department {letter}
                  </option>
                );
              }
            )}
          </select>
        </label>

        {/* BLOCK */}

        {safeFormData.resourceScope === "block" ? (
          <label>
            <span>Block</span>

            <select
              value={safeFormData.blockId}
              onChange={handleBlockChange}
              required
            >
              <option value="">
                Select block
              </option>

              {blockOptions.map((block) => (
                <option
                  key={block.id}
                  value={block.id}
                >
                  Block {block.name}
                </option>
              ))}
            </select>
          </label>
        ) : (
          <div className="readonly-tile">
            <span>Extra Center</span>

            <strong>
              Extra Centers
            </strong>
          </div>
        )}

        {/* RESOURCE */}

        <label>
          <span>Resource</span>

          <select
            name="resourceId"
            value={safeFormData.resourceId}
            onChange={onChange}
            required
            disabled={
              resourceLoading ||
              (
                safeFormData.resourceScope ===
                  "block" &&
                !safeFormData.blockId
              )
            }
          >
            <option value="">
              {resourceLoading
                ? "Loading resources..."
                : resourceRows.length
                  ? "Select resource"
                  : "No resources found"}
            </option>

            {resourceRows.map((resource) => (
              <option
                key={resource.id}
                value={resource.id}
              >
                {formatResourceLabel(resource)}
              </option>
            ))}
          </select>
        </label>

        {resourceError ? (
          <div className="notice danger full-width">
            {resourceError}

            <button
              type="button"
              className="inline-button"
              onClick={loadResources}
            >
              Retry
            </button>
          </div>
        ) : null}

        {/* DATE */}

        <label>
          <span>Date</span>

          <input
            type="date"
            name="bookingDate"
            value={safeFormData.bookingDate}
            onChange={onChange}
            min={today}
            required
          />
        </label>

        {/* START TIME */}

        <label>
          <span>Start Time</span>

          <input
            type="time"
            name="startTime"
            value={safeFormData.startTime}
            onChange={onChange}
            required
          />
        </label>

        {/* STUDENT DURATION */}

        {isStudent ? (
          <label>
            <span>Booking Duration</span>

            <select
              name="duration"
              value={safeFormData.duration}
              onChange={onChange}
              required
            >
              {STUDENT_DURATION_OPTIONS.map(
                (option) => (
                  <option
                    key={option.value}
                    value={option.value}
                  >
                    {option.label}
                  </option>
                )
              )}
            </select>
          </label>
        ) : (
          /* TEACHER END TIME */

          <label>
            <span>End Time</span>

            <input
              type="time"
              name="endTime"
              value={safeFormData.endTime}
              onChange={onChange}
              required
            />
          </label>
        )}

        {/* PURPOSE */}

        <label className="full-width">
          <span>Purpose</span>

          <textarea
            name="purpose"
            value={safeFormData.purpose}
            onChange={onChange}
            required
          />
        </label>

        <div className="form-actions full-width">
          <button
            type="button"
            className="secondary-action"
            onClick={onAvailabilityCheck}
            disabled={
              loading || resourceLoading
            }
          >
            Check Availability
          </button>

          <button
            type="submit"
            className="primary-action"
            disabled={
              loading || resourceLoading
            }
          >
            {loading
              ? "Submitting..."
              : "Submit Booking Request"}
          </button>
        </div>
      </form>

      {availabilityMsg ? (
        <div
          className={`modal-backdrop ${
            availabilityMsg.type === "success"
              ? "success-backdrop"
              : "danger-backdrop"
          }`}
          role="presentation"
        >
          <div className="modal-card glass-panel availability-modal">
            <h3>
              {availabilityMsg.type === "success"
                ? "Available"
                : "Unavailable"}
            </h3>

            <p>
              {availabilityMsg.message}
            </p>

            {availabilityMsg.conflict ? (
              <div className="conflict-box">
                <strong>Conflict</strong>

                <span>
                  {
                    availabilityMsg.conflict.date
                  }{" "}
                  {
                    String(
                      availabilityMsg.conflict
                        .start_time
                    ).slice(0, 5)
                  }
                  {" - "}
                  {
                    String(
                      availabilityMsg.conflict
                        .end_time
                    ).slice(0, 5)
                  }
                </span>
              </div>
            ) : null}

            <button
              type="button"
              className="primary-action"
              onClick={() =>
                onChange({
                  target: {
                    name: "dismissAvailability",
                    value: "",
                  },
                })
              }
            >
              Close
            </button>
          </div>
        </div>
      ) : null}

      {successBooking ? (
        <div
          className="modal-backdrop success-backdrop"
          role="presentation"
        >
          <div className="modal-card glass-panel availability-modal">
            <h3>
              Booking Request Submitted Successfully
            </h3>

            <p>
              {successBooking.resource?.name ||
                `Resource #${successBooking.resource_id}`}
            </p>

            <div className="conflict-box success">
              <span>
                {successBooking.booking_date}
              </span>

              <span>
                {String(
                  successBooking.start_time
                ).slice(0, 5)}
                {" - "}
                {String(
                  successBooking.end_time
                ).slice(0, 5)}
              </span>

              <strong>
                Status: Pending
              </strong>
            </div>

            <button
              type="button"
              className="primary-action"
              onClick={() =>
                onChange({
                  target: {
                    name: "dismissSuccess",
                    value: "",
                  },
                })
              }
            >
              Done
            </button>
          </div>
        </div>
      ) : null}
    </section>
  );
};

export default memo(BookingForm);
